const DEFAULT_SUPABASE_URL = "https://lzypxingcykvgxdifccq.supabase.co";
const DEFAULT_PUBLISHABLE_KEY = "sb_publishable_BOYKDhcighKMhX4k3I6RBw_F-B2jaPY";
const FETCH_TIMEOUT_MS = 9000;

function fetchWithTimeout(url, options = {}) {
  return fetch(url, { ...options, signal: AbortSignal.timeout(FETCH_TIMEOUT_MS) });
}
async function readJson(response) {
  const text = await response.text();
  if (!text) return {};
  try { return JSON.parse(text); } catch { return {}; }
}
function decodeResult(value) {
  let current = value;
  for (let i = 0; i < 3; i += 1) {
    if (Array.isArray(current) && current.length === 1) current = current[0];
    if (typeof current === "string") { try { current = JSON.parse(current); continue; } catch { break; } }
    if (current && typeof current === "object" && "data" in current) { current = current.data; continue; }
    break;
  }
  return current && typeof current === "object" ? current : {};
}
async function activeSubscription(url, key, token) {
  const response = await fetchWithTimeout(url + "/rest/v1/rpc/nexora_my_subscription_status_v264", {
    method: "POST",
    headers: { apikey: key, Authorization: "Bearer " + token, "Content-Type": "application/json" },
    body: JSON.stringify({ p_product_code: "all" })
  });
  if (!response.ok) throw new Error("SUBSCRIPTION_CHECK_FAILED");
  const data = decodeResult(await readJson(response));
  const now = Date.parse(data.server_now || "") || Date.now();
  const end = Date.parse(data.ends_at || "") || 0;
  return data.active === true && String(data.status || "") === "active" && end > now;
}

export default async function handler(request, response) {
  response.setHeader("Cache-Control", "private, no-store, max-age=0, must-revalidate");
  response.setHeader("Pragma", "no-cache");
  response.setHeader("Expires", "0");
  response.setHeader("Content-Type", "application/json; charset=utf-8");
  response.setHeader("Vary", "Authorization");
  response.setHeader("X-Content-Type-Options", "nosniff");
  if (request.method !== "GET") { response.setHeader("Allow", "GET"); return response.status(405).json({success:false,message:"Méthode refusée."}); }
  try {
    const authorization = String(request.headers.authorization || "");
    const token = authorization.startsWith("Bearer ") ? authorization.slice(7).trim() : "";
    if (!token || token.length > 10000) return response.status(401).json({success:false,message:"Connexion Nexora obligatoire."});
    const url = String(process.env.SUPABASE_URL || DEFAULT_SUPABASE_URL).replace(/\/$/, "");
    const key = String(process.env.SUPABASE_PUBLISHABLE_KEY || DEFAULT_PUBLISHABLE_KEY);
    const userResponse = await fetchWithTimeout(url + "/auth/v1/user", { headers: { apikey:key, Authorization:"Bearer "+token } });
    if (!userResponse.ok) return response.status(401).json({success:false,message:"Session Nexora invalide ou expirée."});
    const user = await readJson(userResponse);
    if (!user || !user.id) return response.status(401).json({success:false,message:"Compte Nexora introuvable."});
    if (!(await activeSubscription(url,key,token))) return response.status(403).json({success:false,message:"Un abonnement Nexora actif est nécessaire pour ouvrir la 4ème année."});
    return response.status(200).json({success:true,version:"v520.1",ce2:CE2});
  } catch (error) {
    console.error("Nexora ce2-v520", error && error.message ? error.message : error);
    return response.status(503).json({success:false,message:"4ème année momentanément indisponible. Réessayez dans quelques instants."});
  }
}
